import React, { useState } from 'react';
import { 
  Eye, Trash2, X, MapPin, Clock, ShieldAlert,
  CheckCircle2, HardDrive, AlertTriangle, ChevronRight
} from 'lucide-react';

const ReportsTab = () => {
  const [filter, setFilter] = useState('ALL');
  const [selectedReport, setSelectedReport] = useState(null);

  const complaints = [
    { id: 'REP-772', category: 'SENSOR', code: 'SENS_ERR_01', title: 'Hardware calibration required for Node_77', area: 'GANDHI_NAGAR', zone: 'ZONE_04', time: '20/03/2026', desc: 'Ultrasonic sensor reporting negative values consistently for 4 hours. Likely lens obstruction or hardware drift.', priority: 'HIGH' },
    { id: 'REP-881', category: 'WORKER', code: 'WRK_REP_22', title: 'Illegal dumping detected at Point_B', area: 'SILICON_VALLEY_HQ', zone: 'ZONE_01', time: '21/03/2026', desc: 'Construction debris found next to organic bin. Requires specialized removal vehicle.', priority: 'URGENT' },
    { id: 'REP-902', category: 'CITIZEN', code: 'CIT_APP_09', title: 'Bin lid broken - Sector 5', area: 'OLD_TOWN', zone: 'ZONE_02', time: '22/03/2026', desc: 'Citizen reported via app that the smart-lock is jammed and the lid is partially detached.', priority: 'MEDIUM' },
  ];

  const filteredData = filter === 'ALL' ? complaints : complaints.filter(c => c.category === filter);

  return (
    <div className="w-full h-full flex flex-col gap-6 font-black italic uppercase tracking-tighter select-none pb-10">

      {/* 🏷️ FILTER STRIP */}
      <div className="flex flex-wrap gap-3 shrink-0">
        {['ALL', 'WORKER', 'SENSOR', 'CITIZEN'].map(cat => (
          <button 
            key={cat}
            onClick={() => setFilter(cat)}
            className={`px-6 py-3 border-[4px] border-[#47510B] rounded-2xl transition-all shadow-[4px_4px_0_0_#47510B] text-xs ${filter === cat ? 'bg-[#AB1717] text-white' : 'bg-white text-[#47510B]'}`}
          >
            {cat}_REPORTS
          </button>
        ))}
      </div>

      {/* 🖥️ MAIN CONTENT AREA (Split Layout for Laptops) */}
      <div className="flex-grow flex flex-col lg:flex-row gap-6 overflow-hidden">

        {/* 📋 LEFT: FEED OF REPORTS */}
        <div className={`flex-grow lg:w-3/5 overflow-y-auto pr-2 custom-scrollbar flex flex-col gap-4 ${selectedReport ? 'hidden lg:flex' : 'flex'}`}>
          {filteredData.map((report) => (
            <div 
              key={report.id}
              onClick={() => setSelectedReport(report)}
              className={`p-6 rounded-[35px] border-[4px] border-[#47510B] transition-all cursor-pointer flex justify-between items-center bg-white shadow-[6px_6px_0_0_#47510B] hover:translate-x-1 ${selectedReport?.id === report.id ? 'bg-[#FDFAD8] border-[#AB1717] shadow-[6px_6px_0_0_#AB1717]' : ''}`}
            >
              <div className="min-w-0">
                <div className="flex items-center gap-2 mb-2">
                   <span className={`text-[9px] font-black px-2 py-0.5 rounded border-2 border-black ${
                       report.category === 'SENSOR' ? 'bg-[#A1AED1]' : 
                       report.category === 'WORKER' ? 'bg-[#FFF24D]' : 'bg-[#CAD23C]'
                     }`}>
                       {report.code}
                   </span>
                   <span className="text-[10px] opacity-40">{report.time}</span>
                </div>
                <h3 className="text-lg md:text-xl text-[#47510B] truncate leading-none">{report.title}</h3>
                <p className="text-[10px] mt-1 text-[#AB1717]">{report.area} // {report.zone}</p>
              </div>
              <ChevronRight size={24} className="text-[#47510B] shrink-0 ml-4" />
            </div>
          ))}
        </div>

        {/* 🚩 RIGHT: ACTION PANEL (Details) */}
        <div className={`lg:w-2/5 flex flex-col bg-[#FDFAD8] border-[6px] border-[#47510B] rounded-[50px] shadow-[12px_12px_0_0_#000] overflow-hidden ${selectedReport ? 'flex' : 'hidden lg:flex opacity-30 grayscale'}`}>
          {selectedReport ? (
            <>
              {/* PANEL HEADER */}
              <div className="bg-[#AB1717] p-6 text-white border-b-[6px] border-[#47510B] flex justify-between items-center shrink-0">
                <div className="flex items-center gap-4">
                  <ShieldAlert size={28} strokeWidth={3} />
                  <div>
                    <p className="text-[10px] opacity-80 leading-none mb-1">REF: {selectedReport.id}</p>
                    <h2 className="text-xl leading-none">REPORT_DOSSIER</h2>
                  </div>
                </div>
                <button onClick={() => setSelectedReport(null)} className="lg:hidden bg-white text-[#AB1717] p-1 rounded-lg border-2 border-black">
                  <X size={20}/>
                </button>
              </div>

              {/* PANEL BODY */}
              <div className="p-8 space-y-6 overflow-y-auto custom-scrollbar flex-grow">
                <div className="grid grid-cols-2 gap-4">
                   <div className="bg-white p-4 rounded-2xl border-4 border-[#47510B] shadow-[4px_4px_0_0_#CAD23C]">
                      <label className="text-[9px] text-[#AB1717] font-bold block mb-1">LOCATION</label>
                      <p className="text-sm font-black text-[#47510B]">{selectedReport.area}</p>
                   </div>
                   <div className="bg-white p-4 rounded-2xl border-4 border-[#47510B] shadow-[4px_4px_0_0_#A1AED1]">
                      <label className="text-[9px] text-[#AB1717] font-bold block mb-1">STATION</label>
                      <p className="text-sm font-black text-[#47510B]">{selectedReport.zone}</p>
                   </div>
                </div>

                <div className="bg-white p-6 rounded-[35px] border-4 border-[#47510B] shadow-[6px_6px_0_0_#47510B]">
                   <label className="text-[10px] bg-[#FFF24D] px-2 py-1 rounded border-2 border-black font-black mb-4 inline-block">INCIDENT_SUMMARY</label>
                   <h4 className="text-lg text-[#47510B] mb-3 leading-tight">{selectedReport.title}</h4>
                   <p className="text-xs italic font-bold text-[#47510B]/60 leading-relaxed lowercase first-letter:uppercase">
                     {selectedReport.desc}
                   </p>
                </div>

                {/* DISPATCH ACTIONS */}
                <div className="mt-auto space-y-4 pt-4">
                   <button className="w-full bg-[#CAD23C] border-4 border-[#47510B] p-4 rounded-2xl font-black shadow-[4px_4px_0_0_#47510B] hover:-translate-y-1 transition-all">
                     DISPATCH_FIELD_UNIT
                   </button>
                   <button onClick={() => setSelectedReport(null)} className="w-full bg-[#47510B] text-white border-4 border-[#CAD23C] p-4 rounded-2xl font-black shadow-[4px_4px_0_0_#000]">
                     MARK_AS_RESOLVED
                   </button>
                </div>
              </div>
            </>
          ) : (
            <div className="flex-grow flex flex-col items-center justify-center p-10 text-center space-y-4">
              <AlertTriangle size={64} className="text-[#47510B]" />
              <p className="text-xl text-[#47510B]">SELECT_A_REPORT<br/>TO_VIEW_DETAILS</p>
            </div>
          )}
        </div>

      </div>
    </div>
  );
};

export default ReportsTab;
